# Example based on: https://docs.litestar.dev/latest/usage/requests.html#file-uploads
from typing import Annotated

from litestar import Litestar, MediaType, post
from litestar.datastructures import UploadFile
from litestar.enums import RequestEncodingType
from litestar.exceptions import HTTPException
from litestar.openapi.config import OpenAPIConfig
from litestar.openapi.plugins import SwaggerRenderPlugin
from litestar.params import Body
from pydantic import BaseModel

swagger_plugin = SwaggerRenderPlugin(version="5.1.3")  # , path="/swagger"

openapi_config = OpenAPIConfig(
    title="Test Litestar File Upload",
    description="Test Litestar File Upload",
    version="1.0.0",
    render_plugins=[swagger_plugin],
    path="/docs",
)


class FileUpload(BaseModel):
    filename: str
    content: str
    size: int


@post(path="/", media_type=MediaType.JSON)
async def handle_file_upload(
    file: Annotated[UploadFile, Body(media_type=RequestEncodingType.MULTI_PART)],
) -> FileUpload:
    if not file.filename:
        raise HTTPException(status_code=400, detail="No file provided")

    try:
        content = await file.read()
        return FileUpload(
            filename=file.filename,
            content=content.decode(),
            size=len(content),
        )
    except UnicodeDecodeError:
        raise HTTPException(
            status_code=400, detail="File must contain valid text content"
        )
    finally:
        await file.close()


app = Litestar(route_handlers=[handle_file_upload], openapi_config=openapi_config)
