async def foo() -> None:
    return None


@get("/bar", status_code=204)
async def bar() -> Response[None]:
    return Response(None)


app = Litestar(
    [foo, bar],
    on_startup=[
        lambda app: print(json.dumps(app.openapi_schema.to_schema(), indent=2))
    ],
)
